      'body' => '<h2>Hospitality Academy کیا ہے؟</h2><p>Hospitality Academy، ریاض، سعودی عرب میں قائم ہاسپیٹیلٹی اور بزنس اسٹریٹجی فرم Altus Advisory کی عوامی ٹریننگ اکیڈمی ہے۔ یہ altus Hospitality Knowledge &amp; Performance پلیٹ فارم پر چلتی ہے، جو ہوٹل اسٹاف کو جاب رول کے مطابق ٹریننگ دیتا ہے اور پھر جانچتا ہے کہ ہر فرد واقعی کام کر سکتا ہے یا نہیں۔</p><h2>یہ عام آن لائن کورس سے کیسے مختلف ہے؟</h2><p>کورس مکمل کر لینے کو ثبوت نہیں سمجھا جاتا۔ ہر سیکھنے والا عہدے کے مطابق تعلیم سے تھیوری اور عملی اسیسمنٹ کی طرف بڑھتا ہے، اور نتیجہ طے شدہ مہارتوں کے مطابق ریکارڈ کیا جاتا ہے۔ جہاں کوئی کمی سامنے آئے وہاں ایکشن پلان اور دوبارہ اسیسمنٹ ہوتا ہے، تاکہ مینیجرز کو مکمل شدہ ویڈیوز کی فہرست کے بجائے صلاحیت کا ثبوت نظر آئے۔</p><ol><li>جاب رول کے تقاضوں کے مطابق تفویض کی گئی تعلیم</li><li>ایک ہی معیار پر تھیوری اسیسمنٹ اور عملی اسیسمنٹ</li><li>مہارت کا ریکارڈ، نشاندہی شدہ کمیاں اور اصلاحی ایکشن پلان</li><li>دوبارہ اسیسمنٹ، تیاری کی حیثیت اور قابلِ تصدیق سرٹیفکیٹ</li></ol><h2>اکیڈمی ہوٹل کے کن شعبوں کا احاطہ کرتی ہے؟</h2><p>مرکزی نصاب دس بنیادی پیشہ ورانہ شعبوں میں ترتیب دیا گیا ہے: ہوٹل کی بنیادی باتیں، فرنٹ آفس، ہاؤس کیپنگ، فوڈ اینڈ بیوریج، کچن، سیلز اور مارکیٹنگ، ریونیو اور ریزرویشنز، گیسٹ ایکسپیرینس، کوالٹی اور آڈٹ، اور سیکیورٹی اور سیفٹی۔ <a href="/en/courses">کورس کیٹلاگ</a> دیکھیں یا کسی مخصوص عہدے کے لیے منظم <a href="/en/learning-paths">لرننگ پاتھ</a> پر چلیں۔</p><h2>ہوٹل اسٹاف کن زبانوں میں سیکھ سکتا ہے؟</h2><p>عربی اور انگریزی ایک ہی تجربے کے طور پر شامل ہیں، اور عربی دائیں سے بائیں ترتیب میں ہے۔ اسٹاف ورک اسپیس ہندی، اردو، فلپائنی، بنگالی، نیپالی اور ملیالم کو بھی سپورٹ کرتی ہے، تاکہ ہر شفٹ پر کام انجام دینے والے لوگ معیار کو سمجھ سکیں۔</p><h2>کیا آجر سرٹیفکیٹ کی جانچ کر سکتا ہے؟</h2><p>جی ہاں۔ ہر سرٹیفکیٹ پر ایک منفرد نمبر اور تصدیقی کوڈ ہوتا ہے، اور کوئی بھی <a href="/en/verify">سرٹیفکیٹ کی تصدیق کے صفحے</a> پر دیکھ سکتا ہے کہ وہ درست ہے، میعاد ختم ہو چکی ہے یا منسوخ ہے۔</p><h2>اکیڈمی Vision 2030 کی کیسے معاونت کرتی ہے؟</h2><p>Vision 2030 کا ہدف 2030 تک مملکت میں سالانہ 150 ملین دورے ہیں، اور یہ اس ترقی کے مرکز میں سعودی انسانی سرمائے کو رکھتا ہے۔ Altus Advisory دو لسانی لرننگ پاتھس، جانچی گئی مہارت اور ایسی سرٹیفیکیشن کے ذریعے اکیڈمی کو ان اہداف سے ہم آہنگ کرتی ہے جس پر سعودی عرب اور GCC کے ہوٹل اعتماد کر سکیں۔</p><p>ہوٹل مالکان اور آپریٹرز <a href="/en/hotels">اپنی پراپرٹیز کے لیے ٹریننگ ترتیب دے سکتے ہیں</a> یا <a href="/en/contact">ریاض میں اکیڈمی ٹیم سے بات کر سکتے ہیں</a>۔</p>',
      'cta_label' => 'کورس کیٹلاگ دیکھیں',
