      'subtitle' => 'ریاض میں Altus Advisory کی عوامی ٹریننگ اکیڈمی: مواد کے پیچھے کون ہے، اس کی منظوری کیسے ہوتی ہے، اور ہم کیا دعویٰ کریں گے اور کیا نہیں۔',
      'body' => '<h2>Hospitality Academy کون چلاتا ہے؟</h2><p>Hospitality Academy کو Altus Advisory چلاتی ہے، جو ریاض، مملکتِ سعودی عرب میں ہیڈکوارٹر رکھنے والی ایک بوتیک اسٹریٹجی فرم ہے اور GCC اور MENA بھر میں کلائنٹس کو خدمات فراہم کرتی ہے۔ Altus دو مربوط شعبوں، Hospitality Solutions اور Business Growth Solutions، کے ذریعے کام کرتی ہے، اور اکیڈمی وہ ذریعہ ہے جس سے اس کے آپریٹنگ معیارات براہِ راست ہوٹل ٹیموں تک پہنچتے ہیں۔</p><h2>ٹریننگ کا مواد کس تجربے پر مبنی ہے؟</h2><p>مواد Altus کے بانیوں کے آپریٹنگ معیارات پر مبنی ہے، جن کا مشترکہ قیادتی تجربہ 60 سال سے زیادہ ہے اور جو Marriott، IHG، Starwood اور Accor کے نظاموں اور آزاد ہوٹلوں میں حاصل کیا گیا۔ ٹریننگ کسی عمومی کورس لائبریری سے نہیں بلکہ ان اسٹینڈرڈ آپریٹنگ پروسیجرز سے شروع ہوتی ہے جیسے وہ شفٹ پر انجام دیے جاتے ہیں۔</p><h2>اکیڈمی کا altus پلیٹ فارم سے کیا تعلق ہے؟</h2><p>اکیڈمی altus Hospitality Knowledge &amp; Performance پلیٹ فارم کا عوامی داخلی دروازہ ہے۔ پلیٹ فارم کے اندر ہوٹل عہدے کے مطابق تعلیم تفویض کرتے ہیں، تھیوری اور عملی اسیسمنٹس کرتے ہیں، مہارت کی کمیوں اور ایکشن پلانز پر نظر رکھتے ہیں، اور ہر ملازم کی تیاری دیکھتے ہیں۔ ایک منضبط AI اسسٹنٹ عملے کے سوالات کا جواب صرف منظور شدہ مواد سے دیتا ہے اور جب وہ مواد کسی سوال کا احاطہ نہ کرے تو یہ صاف بتا دیتا ہے۔</p><h2>ٹریننگ کے مواد کی منظوری کیسے ہوتی ہے؟</h2><p>ہر سبق، طریقۂ کار اور اسیسمنٹ سیکھنے والوں کے سامنے آنے سے پہلے ایک منضبط جائزے سے گزرتا ہے۔</p><ol><li>مصنف مسودہ تیار کرتا ہے۔</li><li>مسودے کو اندرونی منظوری ملتی ہے۔</li><li>مسودے کو کوالٹی کی منظوری ملتی ہے۔</li><li>مواد شائع کیا جاتا ہے اور اس کا ورژن ریکارڈ کیا جاتا ہے۔</li></ol><p>مصنفین اپنے کام کی خود منظوری نہیں دے سکتے، اور پچھلے ورژنز ریکارڈ میں رہتے ہیں تاکہ آڈیٹر دیکھ سکے کہ کسی بھی تاریخ کو کون سا معیار لاگو تھا۔</p><h2>اکیڈمی کن اصولوں پر چلتی ہے؟</h2><p>اکیڈمی ان اصولوں پر عمل کرتی ہے جو Altus Advisory ہر ذمہ داری میں لاگو کرتی ہے۔</p><ul><li>اندازے کے بجائے ثبوت: صلاحیت اسیسمنٹ سے ظاہر ہوتی ہے، حاضری سے فرض نہیں کی جاتی۔</li><li>ایسے معیارات جو ہر شفٹ پر قائم رہیں، عربی، انگریزی اور ان زبانوں میں جو ہوٹل اسٹاف استعمال کرتا ہے۔</li><li>ذمہ داری سے آگے شراکت: کام ختم ہونے کے بعد بھی علم کلائنٹ ادارے کے اندر رہتا ہے۔</li><li>سعودائزیشن اور نوجوانوں کو بااختیار بنانے کے Vision 2030 کے اہداف کے مطابق سعودی انسانی سرمائے کی معاونت۔</li></ul><h2>اکیڈمی کیا دعویٰ نہیں کرتی؟</h2><p>یہ سائٹ پاس ہونے کی شرح، کلائنٹس کی توثیق یا ایکریڈیٹیشن کے دعوے شائع نہیں کرتی۔ سرٹیفکیٹ بالکل وہی بیان کرتا ہے جو وہ ریکارڈ کرتا ہے: کس نے کون سا کورس یا پروگرام مکمل کیا، کس تاریخ کو، کس نتیجے کے ساتھ، اور آیا وہ اب بھی درست ہے۔ پڑھیں کہ <a href="/en/certificates">سرٹیفیکیشن کیسے کام کرتی ہے</a>، یا <a href="/en/altus">Altus Advisory اور اس کی خدمات</a> کے بارے میں مزید جانیں۔</p>',
