    array (
      'title' => 'سعودی عرب کی پراپرٹیز کے لیے ہوٹل ٹریننگ پلیٹ فارم',
      'subtitle' => 'عہدے کے مطابق تعلیم تفویض کریں، تھیوری اور عمل کی جانچ کریں، مہارت کی کمیاں دور کریں اور ہر پراپرٹی کی تیاری دیکھیں، ایک ہی دو لسانی ورک اسپیس میں۔',
      'body' => '<h2>ہوٹلوں کو صرف کورس کی تکمیل نہیں بلکہ صلاحیت کے ثبوت کی ضرورت کیوں ہے؟</h2><p>زیادہ تر ہوٹل پہلے سے جانتے ہیں کہ ان کی ٹیموں کو کیا کرنا چاہیے۔ مشکل یہ ثابت کرنا ہے کہ ہر فرد موجودہ معیار کے مطابق یہ کام کر سکتا ہے، اور کمیوں کو اس سے پہلے تلاش کرنا کہ کوئی مہمان، آڈٹ یا معائنہ انہیں تلاش کرے۔ Altus Advisory نے ریاض اور پورے سعودی عرب کے ہوٹلوں کے لیے یہ خلا پُر کرنے کے لیے altus Hospitality Knowledge &amp; Performance پلیٹ فارم بنایا ہے۔</p><h2>ہوٹل کو پلیٹ فارم سے کیا ملتا ہے؟</h2><p>ایک واحد ورک اسپیس جہاں ہر پراپرٹی کے لیے ٹریننگ، اسیسمنٹ اور ثبوت ایک ساتھ موجود ہوں۔</p><ul><li>افراد، جاب رولز، شعبوں یا گروپوں کو تفویض کی گئی تعلیم، آخری تاریخوں اور استثنیٰ کے ساتھ</li><li>تھیوری اسیسمنٹس اور عملی اسیسمنٹس جن کی اسکورنگ وزن دار روبرکس پر ہوتی ہے، جہاں کوئی کریٹیکل معیار نتیجے کی حد مقرر کر دیتا ہے</li><li>مہارت کے پروفائلز، کمیوں کا ہیٹ میپ، ثبوت اپ لوڈ کرنے کی سہولت کے ساتھ ایکشن پلانز اور دوبارہ اسیسمنٹ</li><li>ہر ملازم کی تیاری کی حیثیت، بشمول پری اوپننگ ٹیموں کے لیے افتتاح کی تیاری</li><li>کوالٹی آڈٹس، KPIs اور CSV اور XLSX میں ایکسپورٹ ہونے والی رپورٹس</li><li>ایک منضبط AI اسسٹنٹ جو صرف آپ کے منظور شدہ SOPs اور پالیسیوں سے، حوالوں کے ساتھ جواب دیتا ہے</li><li>پراپرٹی کی برانڈنگ: آپ کا لوگو، رنگ اور نام</li></ul><h2>پلیٹ فارم کے اندر کون کیا دیکھتا ہے؟</h2><p>رسائی آپ کے ادارے کی ساخت کے مطابق ہوتی ہے۔ شعبے کا سربراہ اپنی ٹیم دیکھتا ہے، جنرل مینیجر پراپرٹی دیکھتا ہے، اور ایگزیکٹو پورٹ فولیو کا جائزہ اور قابلِ پرنٹ بورڈ رپورٹ دیکھتا ہے۔ ہر مرحلہ آپ کے ادارے تک محدود ہے اور آڈٹ لاگ میں ریکارڈ ہوتا ہے، اور کوئی ادارہ کسی دوسرے ادارے کا ڈیٹا نہیں دیکھ سکتا۔</p><h2>پلیٹ فارم کن پراپرٹیز کے لیے بنایا گیا ہے؟</h2><p>Altus Advisory کے کارپوریٹ پروفائل کے مطابق، یہ پلیٹ فارم خاص طور پر سعودی عرب اور عرب خطے کے آزاد ہوٹلوں، سروسڈ اپارٹمنٹس اور SME اداروں کے لیے بنایا گیا ہے جنہیں عالمی چین کے نظاموں کی لاگت اور پیچیدگی کے بغیر عملی، معیار پر مبنی ٹریننگ درکار ہے۔ یہ ضرورت بڑھ رہی ہے: سعودی وزارتِ سیاحت کے ابتدائی اعداد و شمار 2025 میں 122 ملین ملکی اور بین الاقوامی دورے ریکارڈ کرتے ہیں، اور Vision 2030 کا ہدف 2030 تک سالانہ 150 ملین دورے ہیں۔</p><h2>ہم کیسے شروع کریں؟</h2><p>سیٹ اپ خالی کیٹلاگ سے نہیں بلکہ آپ کے ڈھانچے سے شروع ہوتا ہے۔</p><ol><li>اپنی پراپرٹیز، شعبے اور ہر شعبے میں ملازمین کی تقریباً تعداد بتائیں۔</li><li>Altus ادارہ ترتیب دیتی ہے اور جاب رولز کو ان کی مطلوبہ مہارتوں سے جوڑتی ہے۔</li><li>لازمی ٹریننگ تفویض کی جاتی ہے، تاکہ عملہ پہلے لاگ اِن پر اپنی فہرست کھول سکے۔</li><li>مینیجرز اپنے ڈیش بورڈ سے تکمیل، اسیسمنٹ کے نتائج اور تیاری پر نظر رکھتے ہیں۔</li></ol><p><a href="/en/hotels/training">شعبوں کے لحاظ سے ٹریننگ پروگرام</a> دیکھیں، <a href="/en/programs">سرٹیفیکیشن پروگرامز</a> براؤز کریں، یا <a href="/en/contact">اکیڈمی ٹیم سے بات کریں</a>۔</p>',
