      'title' => 'شعبوں کے لحاظ سے ہوٹل اسٹاف ٹریننگ پروگرامز',
      'subtitle' => 'ہوٹل کے ہر شعبے کو کس چیز کی ٹریننگ دی جاتی ہے، کس ترتیب سے دی جاتی ہے، اور ملازم کے بغیر نگرانی کام کرنے سے پہلے صلاحیت کی تصدیق کیسے ہوتی ہے۔',
      'body' => '<h2>ہوٹل کے ہر شعبے کو کس ٹریننگ کی ضرورت ہے؟</h2><p>ہر شعبہ اس مرکزی نصاب کے اندر اپنے ٹریک پر چلتا ہے جو Altus Advisory نے ریاض میں میدان میں آزمودہ آپریٹنگ معیارات سے تیار کیا ہے۔ مواد پیشہ ورانہ شعبے، ٹریک، ماڈیول اور سبق کی صورت میں ترتیب دیا گیا ہے، جس کے بعد اسیسمنٹ اور سرٹیفیکیشن ہوتی ہے، تاکہ ہر عہدے کا ایک واضح راستہ ہو۔</p><ul><li><strong>فرنٹ آفس:</strong> آمد اور روانگی، مہمان کی رجسٹریشن اور رازداری، کمروں کی الاٹمنٹ، شکایات سے نمٹنا، اپ سیلنگ اور نائٹ آڈٹ۔</li><li><strong>ہاؤس کیپنگ:</strong> کمرے کی صفائی کی ترتیب، بستر اور باتھ روم کے معیارات، کیمیکل سیفٹی، گمشدہ اور ملنے والی اشیاء، لانڈری، پبلک ایریاز اور معائنہ۔</li><li><strong>فوڈ اینڈ بیوریج:</strong> سروس کی ترتیب، استقبال اور نشست، ٹیبل اور مشروبات کی سروس، بینکوئٹس اور پوائنٹ آف سیل کا طریقۂ کار۔</li><li><strong>کچن:</strong> فوڈ سیفٹی، درجۂ حرارت کا کنٹرول، ذخیرہ اور وصولی، الرجینز سے نمٹنا، چاقو کی حفاظت اور ضیاع پر کنٹرول۔</li><li><strong>سیلز، ریونیو اور ریزرویشنز:</strong> سیلز اور مارکیٹنگ، ریزرویشنز کا طریقۂ کار، ڈسٹری بیوشن اور ریونیو کی بنیادی باتیں۔</li><li><strong>گیسٹ ایکسپیرینس، کوالٹی اور آڈٹ:</strong> سروس ریکوری، برانڈ اور SOP کی پابندی، اور کوالٹی معائنہ۔</li><li><strong>سیکیورٹی اور سیفٹی:</strong> ہر ملازم کے لیے فائر سیفٹی، ہنگامی ردِعمل اور سیکیورٹی کا طریقۂ کار۔</li></ul><h2>ہوٹل اسٹاف ٹریننگ کس ترتیب سے دی جاتی ہے؟</h2><p>پہلے حفاظت اور بنیادیں، پھر عہدے کی مہارتیں، پھر اسی معیار پر اسیسمنٹ۔</p><ol><li>ہر ملازم کے لیے ہوٹل کی بنیادی باتیں، پراپرٹی انڈکشن اور حفاظت</li><li>عہدے کی پیشگی شرائط، جیسے ہاؤس کیپنگ میں کیمیکل سیفٹی یا کچن میں فوڈ سیفٹی اور الرجینز سے نمٹنا</li><li>ویڈیو، PDF، سلائیڈز یا آڈیو میں مختصر عملی اسباق پر مشتمل عہدے کے ماڈیولز</li><li>تھیوری اسیسمنٹ، اور پھر سپروائزر کی جانب سے عملی اسیسمنٹ</li><li>سرٹیفکیٹ، یا جہاں کمی پائی جائے وہاں ایکشن پلان اور دوبارہ اسیسمنٹ</li></ol><h2>کیا ٹریننگ ہمارے اپنے ہوٹل کے معیارات کے مطابق ہو سکتی ہے؟</h2><p>جی ہاں۔ پلیٹ فارم ہر پراپرٹی کے لیے وائٹ لیبل ہے، اور آپ کے منظور شدہ SOPs، پالیسیاں اور چیک لسٹیں نصاب کے ساتھ موجود رہتی ہیں، اور ہر ورژن پر عملے کی توثیق ریکارڈ کی جاتی ہے۔ AI اسسٹنٹ عملے کے سوالات کا جواب صرف اسی منظور شدہ مواد سے دیتا ہے۔</p><h2>کیا یہ ٹریننگ ان ملازمین کے لیے دستیاب ہے جو عربی یا انگریزی نہیں پڑھتے؟</h2><p>اسباق عربی اور انگریزی میں دو لسانی ہیں، اور اسٹاف ورک اسپیس سعودی عرب بھر کے ہوٹلوں میں کام کرنے والی کثیر القومی ٹیموں کے لیے ہندی، اردو، فلپائنی، بنگالی، نیپالی اور ملیالم کو بھی سپورٹ کرتی ہے۔</p><p><a href="/en/courses">مکمل کورس کیٹلاگ</a> دیکھیں، <a href="/en/learning-paths">عہدے کے مطابق لرننگ پاتھ</a> پر چلیں، یا پڑھیں کہ <a href="/en/hotels">ہوٹل پلیٹ فارم کو کیسے استعمال کرتے ہیں</a>۔</p>',
