      'subtitle' => 'Hospitality Academy کا سرٹیفکیٹ کیا ریکارڈ کرتا ہے، کب جاری ہوتا ہے، اور آجر چند سیکنڈز میں کیسے جانچ سکتا ہے کہ یہ اصلی اور موجودہ ہے۔',
      'body' => '<h2>Hospitality Academy کا سرٹیفکیٹ کب جاری ہوتا ہے؟</h2><p>سرٹیفکیٹ اس وقت جاری ہوتا ہے جب سیکھنے والا کسی کورس کے تمام لازمی اسباق مکمل کر لے اور اس کا اسیسمنٹ اس کورس کے لیے مقرر پاسنگ مارک یا اس سے زیادہ کے ساتھ پاس کر لے۔ پروگرام سرٹیفکیٹ اس وقت جاری ہوتا ہے جب پروگرام کا ہر کورس مکمل ہو جائے۔ سرٹیفیکیشن حاضری کی نہیں بلکہ جانچی گئی صلاحیت کی عکاسی کے لیے بنائی گئی ہے۔</p><h2>ہوٹل ٹریننگ سرٹیفکیٹ کیا ریکارڈ کرتا ہے؟</h2><p>ہر سرٹیفکیٹ وہ حقائق ریکارڈ کرتا ہے جن کی آجر کو ضرورت ہے، اس سے زیادہ کچھ نہیں۔</p><ul><li>سیکھنے والے کا نام</li><li>مکمل کیا گیا کورس یا پروگرام</li><li>تکمیل کی تاریخ اور حتمی اسکور</li><li>ایک منفرد سرٹیفکیٹ نمبر، تصدیقی کوڈ اور QR کوڈ</li><li>میعاد ختم ہونے کی تاریخ، جہاں موضوع کو وقتاً فوقتاً تازہ کرنے کی ضرورت ہو، جیسے سیفٹی اور فوڈ سیفٹی</li></ul><h2>میں ہوٹل ٹریننگ سرٹیفکیٹ کی تصدیق کیسے کروں؟</h2><p>عوامی تصدیقی صفحہ استعمال کریں۔ کسی اکاؤنٹ کی ضرورت نہیں۔</p><ol><li><a href="/en/verify">سرٹیفکیٹ کی تصدیق کا صفحہ</a> کھولیں۔</li><li>سرٹیفکیٹ پر چھپا ہوا تصدیقی کوڈ درج کریں، یا اس کا QR کوڈ اسکین کریں۔</li><li>ظاہر ہونے والی حیثیت پڑھیں: درست، میعاد ختم، منسوخ یا نہیں ملا۔</li></ol><p>درست نتیجہ سیکھنے والے کا نام، موضوع اور اجرا کی تاریخ دکھاتا ہے، اور اس فرد کے بارے میں اور کچھ نہیں۔</p><h2>سرٹیفکیٹ منسوخ کیوں دکھ سکتا ہے؟</h2><p>سرٹیفکیٹ اس صورت میں منسوخ کیا جاتا ہے جب وہ غلطی سے جاری ہوا ہو، اس کے پیچھے اسیسمنٹ کا نتیجہ غلط پایا جائے، یا جاری کرنے والے ادارے کی درخواست پر۔ منسوخ شدہ سرٹیفکیٹ غائب ہونے کے بجائے قابلِ تصدیق رہتا ہے اور منسوخ کی حیثیت ہی دکھاتا رہتا ہے، تاکہ کسی پرانی کاپی کو موجودہ کے طور پر پیش نہ کیا جا سکے۔</p><h2>سرٹیفکیٹس کون جاری کرتا ہے؟</h2><p>سرٹیفکیٹس altus Hospitality Knowledge &amp; Performance پلیٹ فارم کے ذریعے جاری ہوتے ہیں، جسے ریاض، سعودی عرب میں Altus Advisory چلاتی ہے۔ سرٹیفکیٹ کسی مخصوص فرد کی جانب سے کسی مخصوص تاریخ کو کسی مخصوص کورس یا پروگرام کی تکمیل کو ریکارڈ کرتا ہے۔ یہ کوئی لائسنس، ریگولیٹری منظوری یا اس بات کا بیان نہیں کہ حامل کسی خاص عہدے کے لیے اہل ہے۔</p><p>دستیاب <a href="/en/programs">سرٹیفیکیشن پروگرامز</a> دیکھیں یا اپنے ہوٹل اسٹاف کی سرٹیفیکیشن کے بارے میں <a href="/en/contact">اکیڈمی ٹیم سے پوچھیں</a>۔</p>',
      'cta_label' => 'سرٹیفکیٹ کی تصدیق کریں',
