      'body' => '<h2>میں اپنی پراپرٹی کے لیے ہوٹل ٹریننگ کی درخواست کیسے کروں؟</h2><p>ریاض یا مملکت میں کسی اور جگہ ہوٹل ٹریننگ کے بارے میں اپنی درخواست اس صفحے پر موجود فارم کے ذریعے بھیجیں۔ ریاض، مملکتِ سعودی عرب میں Altus Advisory کی Hospitality Academy ٹیم کا ایک رکن کال طے کرنے کے لیے جواب دیتا ہے۔ کوئی خودکار ای میل سلسلہ نہیں، اور آپ کی تفصیلات کسی تیسرے فریق کو نہیں دی جاتیں۔</p><h2>مجھے اپنی درخواست میں کیا شامل کرنا چاہیے؟</h2><p>چند حقائق کی مدد سے ہم عمومی پریزنٹیشن کے بجائے ایک قابلِ عمل ڈھانچے کے ساتھ جواب دے سکتے ہیں۔</p><ul><li>متعلقہ پراپرٹیز اور شہر</li><li>وہ شعبے جن سے آپ شروع کرنا چاہتے ہیں</li><li>ہر شعبے میں ملازمین کی تقریباً تعداد</li><li>وہ زبانیں جن کی آپ کے عملے کو ضرورت ہے: عربی، انگریزی، یا افرادی قوت کی زبانیں جیسے ہندی، اردو، فلپائنی، بنگالی، نیپالی یا ملیالم</li><li>کوئی آخری تاریخ، جیسے پری اوپننگ یا معائنہ</li></ul><h2>رابطہ کرنے کے بعد کیا ہوتا ہے؟</h2><p>یہ عمل مختصر ہے اور اسے خودکار نظام نہیں بلکہ لوگ سنبھالتے ہیں۔</p><ol><li>ہم تعارفی کال طے کرنے کے لیے جواب دیتے ہیں۔</li><li>ہم آپ کی پراپرٹیز، جاب رولز اور موجودہ معیارات پر بات کرتے ہیں۔</li><li>ہم آپ کی ٹیم کے لیے شعبوں، عہدوں اور لازمی ٹریننگ کا ایک ڈھانچہ تجویز کرتے ہیں۔</li></ol><h2>کیا میں ٹریننگ کے علاوہ کسی اور معاملے پر Altus Advisory سے رابطہ کر سکتا ہوں؟</h2><p>جی ہاں۔ Altus Advisory سعودی عرب اور GCC میں ہوٹل مالکان اور سرمایہ کاروں کو ہوٹل ڈیولپمنٹ اور اونر ریپریزنٹیشن، پری اوپننگ سپورٹ، آپریشنز، گیسٹ ایکسپیرینس، تجارتی کارکردگی اور وسیع تر کاروباری ترقی پر بھی مشاورت دیتی ہے۔ <a href="/en/altus">Altus Advisory اور اس کی خدمات</a> کے بارے میں پڑھیں۔</p><h2>سرٹیفکیٹ سے متعلق سوال کے لیے میں کہاں جاؤں؟</h2><p>یہ جاننے کے لیے کہ سرٹیفکیٹ اصلی ہے یا نہیں، براہِ راست <a href="/en/verify">سرٹیفکیٹ کی تصدیق کا صفحہ</a> استعمال کریں؛ کسی درخواست کی ضرورت نہیں۔ اپنے لرننگ ریکارڈ کی کاپی یا اس میں تصحیح کے لیے اپنے آجر کے ایڈمنسٹریٹر سے رابطہ کریں یا اس صفحے کے ذریعے ہمیں لکھیں۔</p><p>لکھنے سے پہلے آپ کے لیے یہ دیکھنا مفید ہو سکتا ہے کہ <a href="/en/hotels">پلیٹ فارم ہوٹلوں کے لیے کیسے کام کرتا ہے</a> یا <a href="/en/courses">کورس کیٹلاگ</a> دیکھ لیں۔</p>',
