      'body' => '<h2>یہ پالیسی کن پر لاگو ہوتی ہے</h2><p>یہ پالیسی Hospitality Academy پر لاگو ہوتی ہے، جو ریاض، مملکتِ سعودی عرب میں Altus Advisory کی چلائی جانے والی ٹریننگ اکیڈمی ہے، اور ان سیکھنے والوں پر جو اسے اپنے آجر کے ذریعے یا براہِ راست استعمال کرتے ہیں۔</p><h2>کیا جمع کیا جاتا ہے</h2><p>سیکھنے والے کے لیے اکیڈمی یہ محفوظ کرتی ہے:</p><ul><li>نام، کام کا ای میل اور موبائل نمبر، جہاں فراہم کیا گیا ہو</li><li>آجر، پراپرٹی، شعبہ اور جاب رول</li><li>لرننگ ریکارڈ: اندراجات، اسباق میں پیش رفت، اسیسمنٹ کی کوششیں اور اسکور، سرٹیفکیٹس اور طریقۂ کار کی توثیقات</li></ul><h2>یہ کیوں جمع کیا جاتا ہے</h2><p>یہ معلومات ان مقاصد کے لیے استعمال ہوتی ہیں:</p><ul><li>ٹریننگ فراہم کرنا</li><li>یہ ریکارڈ کرنا کہ ٹریننگ مکمل ہوئی یا نہیں</li><li>سرٹیفکیٹس جاری کرنا اور ان کی تصدیق کرنا</li><li>آجر کو اپنی افرادی قوت کی کمپلائنس کی صورتحال دیکھنے دینا</li></ul><p>کچھ بھی فروخت نہیں کیا جاتا، اور کچھ بھی اشتہارات کے لیے استعمال نہیں ہوتا۔</p><h2>طریقۂ کار کی توثیقات</h2><p>توثیق میں صارف، طریقۂ کار کا عین ورژن، وقت کی مہر اور نیٹ ورک ایڈریس جہاں سے یہ کی گئی، ریکارڈ ہوتے ہیں۔ یہ دانستہ ہے: جو توثیق کسی فرد، ورژن اور لمحے سے منسلک نہ کی جا سکے وہ کسی چیز کا ثبوت نہیں۔</p><h2>لرننگ ریکارڈ کون دیکھ سکتا ہے</h2><p>لرننگ ریکارڈ یہ دیکھ سکتے ہیں:</p><ul><li>سیکھنے والا</li><li>سیکھنے والے کا لائن مینیجر</li><li>اسی ادارے کے اندر شعبے، پراپرٹی اور ادارے کے ایڈمنسٹریٹرز</li><li>اکیڈمی کا ایڈمنسٹریٹر</li></ul><p>کوئی ادارہ کسی دوسرے ادارے کا ڈیٹا نہیں دیکھ سکتا۔</p><h2>ریکارڈ رکھنے کی مدت</h2><p>لرننگ ریکارڈ اور سرٹیفکیٹس اکاؤنٹ فعال رہنے تک رکھے جاتے ہیں، اور اس کے بعد اس وقت تک جب تک جاری کرنے والے ادارے کو آڈٹ کے لیے ان کی ضرورت ہو۔ سرٹیفکیٹ کا ریکارڈ غیر معینہ مدت تک رکھا جاتا ہے تاکہ تصدیق کام کرتی رہے۔</p><h2>آپ کی درخواستیں</h2><p>سیکھنے والا اپنے ریکارڈ کی کاپی یا اس میں تصحیح کی درخواست اپنے آجر کے ایڈمنسٹریٹر کے ذریعے یا <a href="/en/contact">رابطے کے صفحے</a> کے ذریعے براہِ راست اکیڈمی سے رابطہ کر کے کر سکتا ہے۔ <a href="/en/terms">استعمال کی شرائط</a> میں اکاؤنٹس اور سرٹیفکیٹس کے قواعد درج ہیں۔</p>',
      'cta_label' => 'اکیڈمی سے رابطہ کریں',
