      'meta_description' => 'Hospitality Academy کی پرائیویسی پالیسی: سیکھنے والوں کا کون سا ڈیٹا جمع کیا جاتا ہے، کیوں، لرننگ ریکارڈ کون دیکھ سکتا ہے، اور ریکارڈ اور سرٹیفکیٹس کتنی دیر رکھے جاتے ہیں۔',
