    'terms' => 
    array (
      'title' => 'استعمال کی شرائط',
      'subtitle' => 'وہ شرائط جو اکیڈمی کے استعمال اور اس کے جاری کردہ سرٹیفکیٹس پر لاگو ہوتی ہیں۔',
      'body' => '<h2>دائرہ کار</h2><p>یہ شرائط Hospitality Academy پر لاگو ہوتی ہیں، جسے ریاض، مملکتِ سعودی عرب میں Altus Advisory چلاتی ہے، اور اس کے ذریعے جاری ہونے والے سرٹیفکیٹس پر۔</p><h2>اکاؤنٹس</h2><p>ایک اکاؤنٹ ایک نامزد فرد کا ہوتا ہے۔</p><ul><li>اکاؤنٹ شیئر کرنے کی اجازت نہیں۔</li><li>کسی دوسرے شخص کی جگہ ٹریننگ مکمل کرنے کی اجازت نہیں۔</li></ul><p>ان میں سے کوئی بھی عمل اس سے حاصل ہونے والے کسی بھی سرٹیفکیٹ کو کالعدم کر دیتا ہے اور اکاؤنٹ معطل کرنے کی بنیاد ہے۔</p><h2>اسیسمنٹس</h2><p>اسیسمنٹ کی کوششیں وقت کی مہر اور کوشش نمبر کے ساتھ ریکارڈ کی جاتی ہیں۔ کوششوں کی حد، وقت کی حد اور سوالات کی بے ترتیبی ہر اسیسمنٹ کے لیے طے شدہ ترتیب کے مطابق لاگو ہوتی ہیں۔ ان کنٹرولز کو نظر انداز کر کے حاصل کیا گیا نتیجہ کالعدم ہے۔</p><h2>سرٹیفکیٹس</h2><p>سرٹیفکیٹ کسی مخصوص فرد کی جانب سے کسی مخصوص تاریخ کو کسی مخصوص کورس یا پروگرام کی تکمیل کو ریکارڈ کرتا ہے۔ یہ کوئی لائسنس، ریگولیٹری منظوری، یا اس بات کا بیان نہیں کہ حامل کسی خاص عہدے کے لیے اہل ہے۔ ایسا کوئی بھی استعمال ان شرائط سے باہر ہے۔ سرٹیفکیٹ کی حیثیت <a href="/en/verify">تصدیقی صفحے</a> پر دیکھی جا سکتی ہے۔</p><h2>مواد</h2><p>اکیڈمی کی جانب سے شائع کیا گیا کورس کا مواد اور طریقۂ کار اکیڈمی یا اس ادارے کی ملکیت رہتے ہیں جس نے انہیں تیار کیا۔ کسی ادارے کی جانب سے اپ لوڈ کیے گئے طریقۂ کار اسی ادارے کی ملکیت رہتے ہیں اور کسی دوسرے ادارے کے ساتھ شیئر نہیں کیے جاتے۔</p><h2>دستیابی</h2><p>اکیڈمی سروس کو مسلسل دستیاب رکھنے کی کوشش کرتی ہے لیکن بلا تعطل رسائی کی ضمانت نہیں دیتی۔ جہاں منصوبہ بند مینٹیننس سے رسائی میں تعطل متوقع ہو، اس کا پیشگی اعلان کیا جاتا ہے۔</p><h2>متعلقہ پالیسیاں</h2><p>ذاتی ڈیٹا کو کیسے سنبھالا جاتا ہے، اس کی تفصیل <a href="/en/privacy">پرائیویسی پالیسی</a> میں ہے۔</p>',
