    array (
      'title' => 'فرنٹ آفس ٹریننگ',
      'intro' => '<p>فرنٹ آفس ٹریننگ ان تمام مراحل کا احاطہ کرتی ہے جو مہمان کے ڈیسک پر پہنچنے سے لے کر اس کا فولیو بند ہونے تک پیش آتے ہیں۔ یہ وہ شعبہ ہے جہاں سروس کی ناکامی سب سے زیادہ نمایاں ہوتی ہے اور طریقۂ کار کی غلطی سب سے مہنگی پڑتی ہے، کیونکہ غلط کمرے کی الاٹمنٹ، غیر تصدیق شدہ شناخت یا غلط پوسٹ کیا گیا چارج، یہ سب بعد میں شکایت یا آڈٹ کی خامی کی صورت میں سامنے آتے ہیں۔</p><h2>فرنٹ آفس ٹریننگ میں کیا شامل ہونا چاہیے</h2><p>آمد اور روانگی کے مراحل ترتیب وار، مہمان کی رجسٹریشن اور اس سے بننے والے ریکارڈ، ہوٹل بھرا ہونے کی صورت میں کمروں کی الاٹمنٹ، اندازے کے بجائے ایک طریقے سے شکایات سے نمٹنا، ٹیلیفون کے معیارات، مہمان پر دباؤ ڈالے بغیر اپ سیلنگ، اور نائٹ آڈٹ جو ہوٹل کا دن بند کرتا ہے۔</p><h2>کارآمد ترتیب</h2><p>نئے ایجنٹ کو بغیر نگرانی کی شفٹ پر کام کرنے سے پہلے پہلے بنیادی باتیں اور ٹیلیفون کے آداب، پھر چیک اِن، چیک آؤٹ اور رجسٹریشن، اور پھر پراپرٹی مینجمنٹ سسٹم مکمل کرنا چاہیے۔ شکایات سے نمٹنا اور نائٹ آڈٹ بعد میں آتے ہیں، جب بنیادی ترتیب خودکار ہو جائے۔</p><h2>پیش رفت کیسے ناپی جاتی ہے</h2><p>ہر کورس ایک اسیسمنٹ پر ختم ہوتا ہے، اور آپریشنل کورسز کے ساتھ ایک چیک لسٹ ہوتی ہے جس پر سیکھنے والا اپنے شعبے میں عمل کرتا ہے۔ تکمیل شفٹ کے بجائے فرد کے ریکارڈ میں درج ہوتی ہے، تاکہ مینیجر دیکھ سکے کہ کون اکیلے کام کرنے کے لیے تیار ہے۔</p>',
