    'housekeeping-training' => 
    array (
      'title' => 'ہاؤس کیپنگ ٹریننگ',
      'intro' => '<p>ہاؤس کیپنگ ٹریننگ کا مقصد کمرے کو قابلِ پیش گوئی بنانا ہے۔ ایک ہی کمرہ صاف کرنے والے دو اٹینڈنٹس کا نتیجہ ایک جیسا ہونا چاہیے، اور انسپکٹر کو دونوں کو ایک ہی تحریری معیار کے مطابق اسکور کر سکنا چاہیے۔</p><h2>محنت سے زیادہ ترتیب کیوں اہم ہے</h2><p>ہاؤس کیپنگ کی زیادہ تر ناکامیاں محنت کی نہیں بلکہ ترتیب کی ناکامیاں ہوتی ہیں۔ کیمیکل لگانے سے پہلے باتھ روم صاف کرنا، دروازے کی طرف کے بجائے دور والے کونے کی طرف ویکیوم کرنا، یا جھاڑ پونچھ سے پہلے بستر بنانا، ان سب کا نتیجہ ایسا کمرہ ہوتا ہے جس میں زیادہ وقت لگا اور جو بدتر نظر آتا ہے۔ ترتیب کی ٹریننگ ہی فی کمرہ وقت کو قابلِ پیش گوئی بناتی ہے۔</p><h2>حفاظت معیار کا حصہ ہے</h2><p>کیمیکل سیفٹی کوئی اضافی ماڈیول نہیں۔ ڈائلیوشن، کیمیکل کو اثر کرنے کا وقت دینا، دستانوں کا استعمال، مصنوعات کو کبھی آپس میں نہ ملانا، اور رنگوں کے لحاظ سے کپڑوں کا وہ نظم جو باتھ روم کے کپڑے کو گلاس تک پہنچنے سے روکتا ہے، یہ سب درست صفائی کا حصہ ہیں، اس لیے انہیں صفائی کے ساتھ ہی سکھایا جاتا ہے۔</p><h2>معائنہ دائرہ مکمل کرتا ہے</h2><p>جس اٹینڈنٹ کا معائنہ اسی معیار پر ہو جس کی اسے ٹریننگ دی گئی تھی، اسے مخصوص فیڈ بیک دیا جا سکتا ہے۔ یہاں ٹریننگ اور معائنہ ایک ہی چیک لسٹ استعمال کرتے ہیں، اور اسی وجہ سے ناکام معائنہ بحث کے بجائے رہنمائی کی گفتگو بن جاتا ہے۔</p>',
