    'food-safety-training' => 
    array (
      'title' => 'ہوٹلوں کے لیے فوڈ سیفٹی ٹریننگ',
      'intro' => '<p>فوڈ سیفٹی ٹریننگ وہ ٹریننگ ہے جس کا ثبوت ہوٹل سے سب سے زیادہ مانگا جاتا ہے، اور جس میں کمی کے نتائج مہمان کی شکایت سے کہیں آگے جاتے ہیں۔</p><h2>اہم کنٹرول پوائنٹس</h2><p>وصولی کے وقت درجۂ حرارت، ذخیرے کی ترتیب اور تاریخیں، پکانے کا درجۂ حرارت، ہاٹ ہولڈنگ، ٹھنڈا کرنے کے اوقات، صرف ایک بار دوبارہ گرم کرنا، اور الرجینز کی علیحدگی۔ ہر ایک ایسا مقام ہے جہاں ناکامی کا پتا لگا کر اسے درست کیا جا سکتا ہے، اور ہر ایک سے ایک ریکارڈ بنتا ہے۔</p><h2>ریکارڈ ہی ٹریننگ کا نتیجہ ہے</h2><p>تربیت یافتہ ٹیم ایسا مکمل ٹمپریچر لاگ تیار کرتی ہے جس میں کوئی خانہ خالی نہ ہو اور حد سے باہر ہر ریڈنگ کے سامنے اصلاحی کارروائی درج ہو۔ نامکمل لاگ کاغذی مسئلہ نہیں بلکہ ٹریننگ کی کمی ہے، اس لیے اکیڈمی لاگ کی تکمیل کو انتظامی کام کے بجائے مہارت کا حصہ سمجھتی ہے۔</p><h2>کس کو اس کی ضرورت ہے</h2><p>کچن ٹیموں کو پورا مجموعہ درکار ہے۔ سروس ٹیموں کو پاس پر درجۂ حرارت سے آگاہی، الرجین سے متعلق سوالات اور ذاتی صفائی کی ضرورت ہے۔ وصولی کے کلرکس کو ڈیلیوری کی جانچ درکار ہے۔ ہاؤس کیپنگ کو اس وقت ضرورت ہے جب منی بار یا کمرے میں کھانے پینے کی اشیاء کی فراہمی شامل ہو۔</p>',
    ),
    'hotel-sop-training' => 
    array (
      'title' => 'ہوٹل SOP ٹریننگ',
      'intro' => '<p>جس اسٹینڈرڈ آپریٹنگ پروسیجر کو کسی نے پڑھا نہ ہو وہ محض ایک دستاویز ہے، کنٹرول نہیں۔ SOP ٹریننگ ہی دستاویز کو کنٹرول میں بدلتی ہے۔</p><h2>قابلِ استعمال SOP میں کیا ہوتا ہے</h2><p>مقصد، دائرہ کار، نامزد ذمہ داریاں، درکار آلات، طریقۂ کار نمبر وار مراحل کی صورت میں اسی ترتیب سے جس میں انہیں انجام دیا جاتا ہے، ایک قابلِ عمل چیک لسٹ، حفاظتی ہدایات، قابلِ پیمائش کوالٹی اسٹینڈرڈ، اور ایسکلیشن کا راستہ۔ جس طریقۂ کار میں ایسکلیشن کا راستہ نہ ہو وہی رات کے تین بجے ناکام ہوتا ہے۔</p><h2>ورژنز اور توثیق</h2><p>جب کوئی طریقۂ کار بدلتا ہے تو پچھلا ورژن محفوظ رکھا جاتا ہے اور نیا ورژن تبدیلیوں کے خلاصے، مصنف اور منظوری دینے والے کے ساتھ شائع کیا جاتا ہے۔ جن پر یہ طریقۂ کار لاگو ہوتا ہے ان سب سے نئے ورژن کی توثیق کرائی جاتی ہے، اور توثیق میں ورژن، فرد اور وقت درج ہوتا ہے۔</p><h2>طریقۂ کار سے چیک لسٹ تک</h2><p>اکیڈمی کے ہر طریقۂ کار کے ساتھ اس کی چیک لسٹ ایک قابلِ عمل آئٹم کے طور پر ہوتی ہے، تاکہ سپروائزر مراحل یاد رکھنے کے بجائے شفٹ پر جانچ کر کے اس پر دستخط کر سکے۔</p>',
    ),
    'hospitality-certification' => 
    array (
      'title' => 'ہاسپیٹیلٹی سرٹیفیکیشن',
      'intro' => '<p>سرٹیفیکیشن اس وقت مفید ہے جب وہ کوئی مخصوص چیز ریکارڈ کرے اور اس کی جانچ کوئی ایسا شخص کر سکے جو وہاں موجود نہ تھا۔ اکیڈمی خود کو اسی معیار پر رکھتی ہے۔</p><h2>یہاں سرٹیفکیٹ کا مطلب کیا ہے</h2><p>ایک نامزد شخص نے ایک نامزد کورس کے تمام لازمی اسباق مکمل کیے اور ایک درج شدہ تاریخ کو اس کا اسیسمنٹ پاسنگ مارک یا اس سے زیادہ کے ساتھ پاس کیا۔ اس سے زیادہ کچھ مراد نہیں، اور اس سے زیادہ کچھ چھاپا نہیں جاتا۔</p><h2>تصدیق</h2><p>ہر سرٹیفکیٹ پر سرٹیفکیٹ نمبر اور تصدیقی کوڈ ہوتا ہے۔ ممکنہ آجر، آڈیٹر یا انسپکٹر عوامی تصدیقی صفحے پر کوڈ درج کر کے بغیر اکاؤنٹ کے فوراً اس کی حیثیت دیکھ سکتا ہے۔</p><h2>میعاد کا خاتمہ اور تجدید</h2><p>سیفٹی اور فوڈ سیفٹی سرٹیفکیٹس کی میعاد مقرر ہوتی ہے کیونکہ بنیادی معیار اور فرد کی یادداشت دونوں بدلتے ہیں۔ اکیڈمی میعاد ختم ہونے کے بعد نہیں بلکہ پہلے سیکھنے والے اور اس کے مینیجر کو خبردار کرتی ہے۔</p>',
    ),
    'hotel-compliance-training' => 
    array (
      'title' => 'ہوٹل کمپلائنس ٹریننگ',
      'intro' => '<p>کمپلائنس ٹریننگ ان موضوعات کا مجموعہ ہے جن کا ثبوت ہوٹل کو ہر ملازم کے لیے، مطالبے پر، تاریخ اور نام کے ساتھ پیش کرنے کے قابل ہونا چاہیے۔</p><h2>لازمی مجموعہ</h2><p>فائر سیفٹی اور انخلا، ہنگامی ردِعمل، صفائی کی مصنوعات استعمال کرنے والے ہر شخص کے لیے کیمیکل سیفٹی، کھانے کو ہاتھ لگانے والے ہر شخص کے لیے فوڈ سیفٹی، کچن میں چاقو کی حفاظت، اور مہمانوں کے ریکارڈ تک رسائی رکھنے والے ہر شخص کے لیے مہمان کے ڈیٹا کی رازداری۔</p><h2>ثبوت، حاضری نہیں</h2><p>حاضری شیٹ دکھاتی ہے کہ کون کمرے میں موجود تھا۔ اسیسمنٹ کے نتیجے کے ساتھ تکمیل کا ریکارڈ دکھاتا ہے کہ کس نے اسے سمجھا۔ اکیڈمی دونوں ریکارڈ کرتی ہے، اور رپورٹ دوسرے کی بنیاد پر دیتی ہے۔</p><h2>اسے تازہ رکھنا</h2><p>کمپلائنس کے موضوعات کی میعاد مقرر ہوتی ہے، اور میعاد ختم ہونے کی وارننگ سیکھنے والے اور مینیجر دونوں کو ایک ساتھ جاتی ہے۔ زیرِ التوا اور تاخیر شدہ آئٹمز شعبے اور پراپرٹی کے لحاظ سے نظر آتے ہیں، تاکہ خلا معائنے سے پہلے ہی سامنے آ جائے۔</p>',
