    'hotel-training-jeddah' => 
    array (
      'title' => 'جدہ میں ہوٹل اسٹاف ٹریننگ',
      'intro' => '<p>جدہ میں تفریحی، کارپوریٹ اور ٹرانزٹ طلب کا امتزاج ہے، ساتھ ہی فوڈ اینڈ بیوریج کی مضبوط ثقافت اور کورنیش کے ہوٹلوں کا وہ انداز جہاں ریسٹورنٹ اکثر کمروں سے زیادہ مصروف ہوتا ہے۔</p><h2>اس سے ٹریننگ میں کیا بدلتا ہے</h2><p>یہاں فوڈ اینڈ بیوریج میں گہرائی اہم ہے۔ سروس کی ترتیب، بینکوئٹ آپریشنز، مشروبات کی سروس اور پوائنٹ آف سیل کے نظم کی ٹریننگ اعلیٰ سطح پر دی جاتی ہے، اور آؤٹ لیٹس کے حجم کی وجہ سے کچن ٹیموں پر الرجین اور درجۂ حرارت کے کنٹرول کا بوجھ زیادہ ہوتا ہے۔</p><h2>فیملی اور گروپ سروس</h2><p>فیملی نشست، بڑی پارٹیوں کی سروس اور مجلس طرز کی ترتیب عام ہیں، اس لیے ٹیبل سروس ٹریننگ دو افراد والے ریسٹورنٹ کا تصور کرنے کے بجائے ان ترتیبوں کا واضح طور پر احاطہ کرتی ہے۔</p><h2>جہاں ٹیموں کو عموماً سب سے زیادہ مدد درکار ہوتی ہے</h2><p>مہمانوں کو جلدی کا احساس دلائے بغیر میزیں دوبارہ تیار کرنا، ایک ہی وقت میں چلنے والے ریسٹورنٹ اور بینکوئٹ کے درمیان رابطہ، اور آؤٹ لیٹ مکمل گنجائش پر ہو تب بھی فوڈ سیفٹی ریکارڈ مکمل رکھنا۔</p>',
