      'intro' => '<p>مکہ کے ہوٹل اس پیمانے اور ٹرن اوور کی شرح پر کام کرتے ہیں جو زیادہ تر پراپرٹیز کبھی نہیں دیکھتیں: کمروں کی بہت بڑی تعداد، گروپوں کی آمد و روانگی جو گاڑیوں کے بجائے کوچز میں گنی جاتی ہے، اور سیزنل عروج جو پورے آپریٹنگ معمول کو بدل دیتا ہے۔</p><h2>اس سے ٹریننگ میں کیا بدلتا ہے</h2><p>بڑی تعداد کو سنبھالنا بنیادی مہارت ہے۔ گروپ چیک اِن اور چیک آؤٹ کا طریقۂ کار، روم بلاکنگ، سیکڑوں کمروں میں چابیوں کا کنٹرول، اور بڑے پیمانے پر ہاؤس کیپنگ ٹرن اراؤنڈ، انفرادی مہمان کے لیے ذاتی نوعیت کی خدمت سے زیادہ اہمیت رکھتے ہیں۔</p><h2>بڑے پیمانے پر ہاؤس کیپنگ</h2><p>روم ٹرن اراؤنڈ، ڈیپ کلیننگ کے چکر، لینن کی ترسیل اور پیداواری منصوبہ بندی ایک نظام کے طور پر سکھائے جاتے ہیں، کیونکہ روانگی کی جو لہر بری طرح سنبھالی جائے وہ اسی دن سنبھل نہیں پاتی۔</p><h2>جہاں ٹیموں کو عموماً سب سے زیادہ مدد درکار ہوتی ہے</h2><p>ایک ہی صبح گروپ کی روانگی اور گروپ کی آمد کے درمیان رابطہ، ٹرن اراؤنڈ کے دباؤ میں کمرے کا معیار برقرار رکھنا، اور ایسے مہمانوں کے ساتھ واضح کثیر لسانی رابطہ جن کی ٹیم کے ساتھ کوئی مشترکہ زبان نہ ہو۔</p>',
