      'intro' => '<p>مدینہ میں بھی مکہ کی طرح گروپوں پر مبنی، تیز ٹرن اوور والا انداز ہے، تاہم بہت سی پراپرٹیز میں اوسط قیام طویل ہوتا ہے اور پُرسکون، بغیر جلدی کے مہمان نوازی پر زور ہوتا ہے۔</p><h2>اس سے ٹریننگ میں کیا بدلتا ہے</h2><p>گروپ آپریشنز اب بھی غالب ہیں، لیکن اسٹے اوور سروس اور طویل قیام کے لیے ہاؤس کیپنگ کے معمولات زیادہ اہم ہیں، اور اسی طرح کسی بزرگ یا کم نقل و حرکت والے مہمان کو صبر کے ساتھ اور بغیر اٹکل کے سنبھالنے کی صلاحیت بھی۔</p><h2>رسائی اور مدد</h2><p>کمروں کی الاٹمنٹ کی ٹریننگ میں رسائی کی ضروریات کا واضح طور پر احاطہ کیا جاتا ہے، اور فرنٹ آفس اور ہاؤس کیپنگ ٹیموں کو محدود نقل و حرکت والے مہمان کی مدد کی ٹریننگ دی جاتی ہے، بشمول انخلا کے دوران۔</p><h2>جہاں ٹیموں کو عموماً سب سے زیادہ مدد درکار ہوتی ہے</h2><p>ایسی اسٹے اوور سروس جو طویل قیام والے کمرے کو معیار پر رکھے، زبان کی رکاوٹ کے باوجود شکایات سے نمٹنا، اور فرنٹ آفس، ہاؤس کیپنگ اور سیکیورٹی کے درمیان مدد کی درخواستوں کا رابطہ۔</p>',
